import {Icon} from '@ui-kitten/components';
import {useEffect, useState} from 'react';
import {FlatList, Image, TextInput, TouchableOpacity, View} from 'react-native';
import TextCM from '../../components/Text';
import {styles} from './styles';
import {useNavigation} from '@react-navigation/native';
import {useChatService} from '../../../hooks/apiHooks/useAccountInfoServices';
import Toast from 'react-native-toast-message';
import {Color, Font, NavigationName, String} from '../../../constants';
import {SafeAreaView} from 'react-native-safe-area-context';
import {userUserStore} from '../../../zustand/userStore';
import useDebounce from '../../../hooks/useDebounce';
import {useChatStore} from '../../../zustand/chatStore.ts';
import {IConversation} from '../../../model/interface/chat.interface.ts';
import {useAppSelector} from '../../../hooks/useRedux.ts';

export interface User {
  user_id: number;
  first_name?: string;
  last_name: string;
  email: string;
  image_url?: string;
  cust_id: number;
  org_in: string;
}
const SearchConversation = () => {
  const chatService = useChatService();
  const dataAccount = useAppSelector(state => state.account.dataAccount);
  const navigation = useNavigation<any>();
  const [currentListUser, setCurrentListUser] = useState<User[]>([]);
  const {listUser, setListUser} = userUserStore();
  const [textSearch, setTextSearch] = useState('');
  const textSearchDebounce = useDebounce(textSearch, 500);
  const {listConversation, setListConversation} = useChatStore();

  useEffect(() => {
    if (!textSearchDebounce) {
      setCurrentListUser(listUser);
    }
    const lowerCaseQuery = textSearchDebounce.toLowerCase();
    const newList = listUser.filter(user => {
      const fullName = `${user.first_name || ''} ${
        user.last_name || ''
      }`.toLowerCase();
      const email = user.email.toLowerCase();
      return (
        fullName.includes(lowerCaseQuery) || email.includes(lowerCaseQuery)
      );
    });
    setCurrentListUser(newList);
  }, [textSearchDebounce]);

  const handlePressUser = async (user: User) => {
    try {
      if (user.user_id == dataAccount?.id) {
        Toast.show({
          type: 'error',
          text1: 'Không thể chat với chính mình',
        });
        return;
      }

      const findedConversation = listConversation.find(
        (item: IConversation) => {
          if (
            item.participants.length == 2 &&
            (item.participants[0].user_id == user.user_id ||
              item.participants[1].user_id == user.user_id)
          ) {
            return true;
          }
          return false;
        },
      );
      if (findedConversation) {
        const res = await chatService.getOneOnOneConversation(
          dataAccount.id || 0,
          user.user_id,
        );
        if (res) {
          navigation.navigate(NavigationName.Conversation, {
            conversationId: findedConversation.id,
            conversationName: findedConversation.conversationName,
          });
          return;
        } else {
          Toast.show({
            type: 'error',
            text1: 'Lỗi khi tạo cuộc trò chuyện',
          });
        }
      } else {
        navigation.navigate(NavigationName.Conversation, {
          targetId: [user.user_id],
          conversationName: `${user.first_name} ${user.last_name}`?.trim(),
        });
      }
    } catch (error) {
      Toast.show({
        type: 'error',
        text1: 'Lỗi khi tạo cuộc trò chuyện',
      });
    }
  };

  useEffect(() => {
    setCurrentListUser(listUser);
  }, []);
  return (
    <SafeAreaView
      edges={['top', 'bottom']}
      style={{flex: 1, backgroundColor: Color.White}}>
      <View style={styles.searchContainer}>
        <View style={styles.searchBar}>
          <TouchableOpacity>
            <Icon
              name="search-outline"
              width={20}
              height={20}
              fill={Color.Text}
            />
          </TouchableOpacity>
          <TextInput
            value={textSearch}
            style={styles.searchInput}
            placeholder="Tìm kiếm người hoặc cuộc hội thoại"
            autoFocus={true}
            onChange={e => setTextSearch(e.nativeEvent.text)}
          />
        </View>
        <TouchableOpacity
          style={{}}
          onPress={() => {
            navigation.goBack();
          }}>
          <TextCM style={{color: '#00204d', fontSize: 16}}>Huỷ</TextCM>
        </TouchableOpacity>
      </View>

      <View
        style={{
          padding: 16,
          backgroundColor: Color.White,
          flex: 1,
          borderRadius: 8,
        }}>
        <FlatList
          data={currentListUser}
          keyExtractor={(item, index) => index.toString()}
          renderItem={({item, index}) => {
            return (
              <TouchableOpacity
                onPress={() => {
                  handlePressUser(item);
                }}
                style={{
                  flexDirection: 'row',
                  alignItems: 'center',
                  margin: 8,
                  borderRadius: 8,
                }}>
                <View
                  style={{
                    width: 32,
                    height: 32,
                    borderRadius: 25,
                    justifyContent: 'center',
                    alignItems: 'center',
                    marginRight: 10,
                  }}>
                  <Image
                    width={32}
                    height={32}
                    borderRadius={25}
                    source={{
                      uri: item.image_url || String.DEFAULT_IMAGE,
                    }}
                  />
                </View>
                <View
                  style={{
                    flexDirection: 'column',
                  }}>
                  <TextCM
                    style={{
                      color: '#00204de5',
                      fontFamily: Font.InterRegular400,
                      fontSize: 14,
                    }}>
                    {item.first_name} {item.last_name}
                  </TextCM>
                  <TextCM
                    style={{
                      color: '#00204d99',
                      fontSize: 12,
                      fontFamily: Font.InterRegular400,
                      marginTop: 2,
                    }}>
                    {item.email}
                  </TextCM>
                </View>
              </TouchableOpacity>
            );
          }}
          ItemSeparatorComponent={() => <View style={{height: 1}} />}
        />
      </View>
    </SafeAreaView>
  );
};

export default SearchConversation;
