import {View, Image} from 'react-native';
import TextCM from '../Text';
import {Color, Font, String} from '../../../constants';
import {useAppSelector} from '../../../hooks/useRedux';
import {styles} from './styles';
import {ParticipantListConversation} from '../../../model/interface/chat.interface';
import {User} from '../../../zustand/userStore';

type Props = {
  participants: ParticipantListConversation[];
};

const getAvatarSource = (user: User) => {
  if (user?.image_url) {
    return {uri: user.image_url};
  }
  const firstChar =
    user?.first_name?.charAt(0)?.toLocaleUpperCase() ||
    user?.last_name?.charAt(0)?.toLocaleUpperCase() ||
    '';
  return firstChar;
};

const Avatar = ({participants}: Props) => {
  const dataAccount = useAppSelector(state => state.account.dataAccount);

  // Lọc ra các thành viên khác mình
  const otherParticipants = participants.filter(
    par => par?.user_id !== dataAccount?.id,
  );

  // Lấy avatar cho nhóm 1-1 hoặc avatar chính cho nhóm nhiều người
  const mainParticipant = otherParticipants[0]?.user;
  const mainAvatar = getAvatarSource(mainParticipant as User);

  // Logic cho trường hợp nhóm có nhiều hơn 2 người
  const groupAvatars: any[] = [];
  if (otherParticipants.length > 1) {
    // Lấy ngẫu nhiên 2 người khác nhau trong nhóm (không bao gồm người đầu tiên đã lấy làm mainParticipant)
    const remainingParticipants = [...otherParticipants];
    if (mainParticipant) {
      // Loại bỏ người đầu tiên nếu đã được chọn làm mainParticipant
      const mainParticipantIndex = remainingParticipants.findIndex(
        p => p.user_id === mainParticipant.user_id,
      );
      if (mainParticipantIndex > -1) {
        remainingParticipants.splice(mainParticipantIndex, 1);
      }
    }

    // Shuffle mảng để lấy ngẫu nhiên
    for (let i = remainingParticipants.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [remainingParticipants[i], remainingParticipants[j]] = [
        remainingParticipants[j],
        remainingParticipants[i],
      ];
    }

    // Lấy tối đa 2 người từ danh sách đã shuffle
    for (let i = 0; i < Math.min(1, remainingParticipants.length); i++) {
      groupAvatars.push(getAvatarSource(remainingParticipants[i].user as User));
    }
  }

  const renderAvatarContent = (avatar: ReturnType<typeof getAvatarSource>) => {
    if (typeof avatar === 'string') {
      return (
        <View style={[styles.avatar, styles.avatarNotImageLink]}>
          <TextCM style={styles.textAvatart}>{avatar}</TextCM>
        </View>
      );
    }
    return <Image source={avatar} style={styles.avatar} />;
  };

  const renderGroupAvatar = (avatar: ReturnType<typeof getAvatarSource>) => {
    if (typeof avatar === 'string') {
      return (
        <View style={[styles.groupAvatar, styles.avatarNotImageLink]}>
          <TextCM style={styles.smallTextAvatar}>{avatar}</TextCM>
        </View>
      );
    }
    return <Image source={avatar} style={styles.groupAvatar} />;
  };

  return (
    <View style={styles.avatarContainer}>
      {participants.length > 2 ? (
        <>
          {renderAvatarContent(mainAvatar)}
          <View style={styles.groupAvatarContainer}>
            {groupAvatars.map((avatar, index) => (
              <View key={index}>{renderGroupAvatar(avatar)}</View>
            ))}
          </View>
        </>
      ) : (
        renderAvatarContent(mainAvatar)
      )}
    </View>
  );
};

export default Avatar;
