import {
  Animated,
  Image,
  Pressable,
  TouchableOpacity,
  View,
  Vibration,
} from 'react-native';

import {styles} from './styles';
import TextCM from '../../../../components/Text';
import {Message} from '../../../../../model/interface/chat.interface';
import {Swipeable} from 'react-native-gesture-handler';
import {Color} from '../../../../../constants';
import {Icon} from '@ui-kitten/components';
import {useRef, useState} from 'react';
import {CommonUtils} from '../../../../../utils';
import MenuOnPressMessage from './menu-press-message';
import React from 'react';

type Props = {
  item: Message;
  type: 'me' | 'system' | 'other';
  setMessageReply: React.Dispatch<React.SetStateAction<Message | undefined>>;
  repliedMessage?: Message;
  handleScroll: (options: {
    type: 'top' | 'bottom' | 'message';
    messageId?: string | number;
  }) => void;
};
const MessageItem = React.memo(
  ({item, type, repliedMessage, setMessageReply, handleScroll}: Props) => {
    const [menuVisible, setMenuVisible] = useState(false);
    const [menuAnchor, setMenuAnchor] = useState<{x: number; y: number} | null>(
      null,
    );
    const content = JSON.parse(item.message_content || '{}');
    const hasAttachment = content.attachments && content.attachments.length > 0;

    const swipeableRef = useRef<Swipeable>(null);

    const handleLongPress = (event: any) => {
      Vibration.vibrate(50); // rung 50ms
      const {pageX, pageY} = event.nativeEvent;
      setMenuAnchor({x: pageX, y: pageY}); // lưu vị trí để hiện menu
      setMenuVisible(true);
    };

    const handleReply = () => {
      setMessageReply(item);
      swipeableRef.current?.close();
    };
    const renderRightActions = (
      progress: Animated.AnimatedInterpolation<number>,
      dragX: Animated.AnimatedInterpolation<number>,
    ) => {
      const trans = dragX.interpolate({
        inputRange: [-(40 / 2), 0],
        outputRange: [0, 40 / 2],
        extrapolate: 'clamp',
      });
      const opacity = dragX.interpolate({
        inputRange: [-80, -40, 0],
        outputRange: [1, 0.5, 0],
        extrapolate: 'clamp',
      });

      // const scale = dragX.interpolate({
      //   inputRange: [-80, -40, 0],
      //   outputRange: [1.2, 1.0, 0.8],
      //   extrapolate: 'clamp',
      // });

      return (
        <Animated.View
          style={{
            width: 60,
            justifyContent: 'center',
            alignItems: 'center',
            opacity,
            transform: [{translateX: trans}],
          }}>
          <Icon name="corner-down-left" width={20} height={20} fill="black" />
        </Animated.View>
      );
    };

    const renderRightReplyAction = (
      _progress: Animated.AnimatedInterpolation<number>,
      dragX: Animated.AnimatedInterpolation<number>,
    ) => {
      // Icon sẽ hiện dần lên khi kéo
      const opacity = dragX.interpolate({
        inputRange: [-80, 0], // Kéo sang phải 80px (giá trị âm) thì opacity là 1
        outputRange: [1, 0],
        extrapolate: 'clamp',
      });

      return (
        <Animated.View style={[styles.replyActionContainer, {opacity}]}>
          <Icon name="menu" width={24} height={24} fill={Color.Black} />
        </Animated.View>
      );
    };

    const renderLeftReplyAction = (
      _progress: Animated.AnimatedInterpolation<number>,
      dragX: Animated.AnimatedInterpolation<number>,
    ) => {
      const trans = dragX.interpolate({
        inputRange: [-(40 / 2), 0],
        outputRange: [0, 40 / 2],
        extrapolate: 'clamp',
      });
      const opacity = dragX.interpolate({
        inputRange: [0, 80],
        outputRange: [0, 1],
        extrapolate: 'clamp',
      });

      return (
        <Animated.View
          style={{
            width: 60,
            justifyContent: 'center',
            alignItems: 'center',
            opacity,
            transform: [{translateX: trans}],
          }}>
          <Icon
            name="corner-down-right"
            width={20}
            height={20}
            fill={Color.Black}
          />
        </Animated.View>
      );
    };

    if (type === 'me') {
      return (
        <Swipeable
          ref={swipeableRef}
          friction={2}
          enabled={item.status !== 2}
          // overshootRight={false}
          useNativeAnimations={true}
          renderRightActions={renderRightActions}
          onSwipeableOpen={direction => {
            if (direction === 'right') {
              handleReply();
            }
          }}>
          <Pressable
            onLongPress={event => item.status !== 2 && handleLongPress(event)}
            style={styles.myMessageContainer}>
            {hasAttachment ? (
              <Image
                source={{uri: content?.attachments?.[0]?.sourceURL}}
                style={styles.attachmentImage}
              />
            ) : (
              <>
                {item.status === 2 ? (
                  <View
                    style={[
                      styles.myMessageBubble,
                      {backgroundColor: '#D9D9D9'},
                    ]}>
                    <TextCM style={styles.messageInfoText}>
                      Bạn đã thu hồi tin nhắn
                    </TextCM>
                  </View>
                ) : (
                  <>
                    <View style={styles.myMessageBubble}>
                      {repliedMessage && (
                        <TouchableOpacity
                          onPress={() => {
                            handleScroll({
                              type: 'message',
                              messageId: repliedMessage.message_id,
                            });
                          }}
                          style={{
                            backgroundColor: Color.White,
                            paddingHorizontal: 8,
                            paddingVertical: 8,
                            borderRadius: 5,
                            borderLeftWidth: 3,
                            borderLeftColor: 'blue',
                          }}>
                          <TextCM>{repliedMessage.username}</TextCM>
                          <TextCM numberOfLines={1}>
                            {CommonUtils.getText(
                              repliedMessage.message_content,
                            )}
                          </TextCM>
                        </TouchableOpacity>
                      )}
                      <TextCM style={styles.myMessageText}>
                        {content?.text}
                      </TextCM>
                    </View>
                    <View style={styles.messageInfo}>
                      <TextCM style={styles.messageInfoText}>Bạn</TextCM>
                    </View>
                  </>
                )}
              </>
            )}
          </Pressable>
          {
            <MenuOnPressMessage
              item={item}
              menuVisible={menuVisible}
              setMenuVisible={setMenuVisible}
              menuAnchor={menuAnchor}
              handleReply={handleReply}
            />
          }
        </Swipeable>
      );
    }

    if (type === 'system') {
      return (
        <View style={styles.otherMessageContainer}>
          {hasAttachment ? (
            <Image
              source={{uri: content?.attachments?.[0]?.sourceURL}}
              style={styles.attachmentImage}
            />
          ) : (
            <>
              <View style={styles.otherMessageBubble}>
                <TextCM style={styles.otherMessageText}>{content?.text}</TextCM>
              </View>
              {/* <View style={styles.messageInfo}>
              <TextCM style={styles.messageInfoText}>{item.username}</TextCM>
            </View> */}
            </>
          )}
        </View>
      );
    }

    if (type === 'other') {
      return (
        <Swipeable
          ref={swipeableRef}
          // renderRightActions={renderRightReplyAction}
          renderLeftActions={renderLeftReplyAction}
          friction={2}
          enabled={item.status !== 2}
          // overshootRight={false}
          useNativeAnimations={true}
          onSwipeableOpen={direction => {
            if (direction === 'left') {
              handleReply();
            }
          }}
          // renderRightActions={}
        >
          {item.status === 2 ? (
            <View
              style={[
                styles.myMessageBubble,
                {
                  width: '80%',
                },
                {backgroundColor: '#D9D9D9'},
              ]}>
              <TextCM style={styles.messageInfoText}>
                {item.username} đã thu hồi tin nhắn
              </TextCM>
            </View>
          ) : (
            <Pressable
              onLongPress={event => item.status !== 2 && handleLongPress(event)}
              style={styles.replyContainer}>
              <View style={styles.replyMessageBubble}>
                {repliedMessage && (
                  <TouchableOpacity
                    onPress={() => {
                      handleScroll({
                        type: 'message',
                        messageId: repliedMessage.message_id,
                      });
                    }}
                    style={{
                      backgroundColor: Color.White,
                      paddingHorizontal: 8,
                      paddingVertical: 8,
                      borderRadius: 5,
                      borderLeftWidth: 3,
                      borderLeftColor: 'blue',
                    }}>
                    <TextCM>{repliedMessage.username}</TextCM>
                    <TextCM numberOfLines={1}>
                      {CommonUtils.getText(repliedMessage.message_content)}
                    </TextCM>
                  </TouchableOpacity>
                )}
                <TextCM style={styles.replyText}>{content.text}</TextCM>
              </View>
              <View style={styles.messageInfo}>
                <TextCM style={styles.messageInfoText}>{item.username}</TextCM>
              </View>
            </Pressable>
          )}
          {
            <MenuOnPressMessage
              item={item}
              menuVisible={menuVisible}
              setMenuVisible={setMenuVisible}
              menuAnchor={menuAnchor}
              handleReply={handleReply}
            />
          }
        </Swipeable>
      );
    }

    return null; // Hoặc một view trống nếu không có type nào khớp
  },
);

export default MessageItem;
