import React, {useEffect, useRef} from 'react';
import {View, StyleSheet, Animated} from 'react-native';

const TypingIndicator = () => {
  // Sử dụng useRef để lưu trữ các Animated.Value cho vị trí Y của 3 chấm
  const dot1 = useRef(new Animated.Value(0)).current;
  const dot2 = useRef(new Animated.Value(0)).current;
  const dot3 = useRef(new Animated.Value(0)).current;

  // Mảng chứa các Animated.Value để dễ dàng lặp qua
  const animatedValues = [dot1, dot2, dot3];

  const startAnimation = () => {
    // Độ trễ giữa các animation của từng chấm
    const delayBetweenDots = 150;
    // Chu kỳ animation lên và xuống của một chấm
    const duration = 500;

    // Lặp qua từng chấm để tạo animation độc lập
    // animatedValues.forEach((value, index) => {
    //   Animated.loop(
    //     Animated.sequence([
    //       // Di chuyển lên
    //       Animated.timing(value, {
    //         toValue: -8, // Di chuyển lên 8 đơn vị
    //         duration: duration,
    //         useNativeDriver: true,
    //       }),
    //       // Di chuyển xuống
    //       Animated.timing(value, {
    //         toValue: 0, // Trở về vị trí ban đầu
    //         duration: duration,
    //         useNativeDriver: true,
    //       }),
    //     ]),
    //     {
    //       iterations: -1, // Lặp lại vô hạn
    //     },
    //   ).start();
    // });

    Animated.loop(
      Animated.sequence([
        // Di chuyển lên
        Animated.timing(dot1, {
          toValue: -8, // Di chuyển lên 8 đơn vị
          duration: duration,
          useNativeDriver: true,
        }),
        // Di chuyển xuống
        Animated.timing(dot1, {
          toValue: 0, // Trở về vị trí ban đầu
          duration: duration,
          useNativeDriver: true,
        }),
      ]),
    ).start();

    Animated.loop(
      Animated.sequence([
        // Di chuyển lên
        Animated.timing(dot2, {
          toValue: -8, // Di chuyển lên 8 đơn vị
          duration: duration,
          useNativeDriver: true,
        }),
        // Di chuyển xuống
        Animated.timing(dot1, {
          toValue: 0, // Trở về vị trí ban đầu
          duration: duration,
          useNativeDriver: true,
        }),
      ]),
    );

    Animated.loop(
      Animated.sequence([
        // Di chuyển lên
        Animated.timing(dot3, {
          toValue: -8, // Di chuyển lên 8 đơn vị
          duration: duration,
          useNativeDriver: true,
        }),
        // Di chuyển xuống
        Animated.timing(dot1, {
          toValue: 0, // Trở về vị trí ban đầu
          duration: duration,
          useNativeDriver: true,
        }),
      ]),
    );
  };

  useEffect(() => {
    startAnimation();
  }, []);

  return (
    <View style={styles.container}>
      <Animated.View style={[styles.dot, {transform: [{translateY: dot1}]}]} />
      <Animated.View style={[styles.dot, {transform: [{translateY: dot2}]}]} />
      <Animated.View style={[styles.dot, {transform: [{translateY: dot3}]}]} />
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    flexDirection: 'row',
    alignItems: 'center',
    // Căn giữa các chấm
    justifyContent: 'center',
    height: 20, // Tăng chiều cao để các chấm có không gian di chuyển
  },
  dot: {
    backgroundColor: 'gray',
    width: 6,
    height: 6,
    borderRadius: 3,
    marginHorizontal: 3,
  },
});

export default TypingIndicator;
