import {Menu} from 'react-native-paper';
import {Message} from '../../../../../../model/interface/chat.interface';
import {useAppSelector} from '../../../../../../hooks/useRedux';
import {useWebSocketStore} from '../../../../../../zustand/useWebSocketStore';
import {useChatStore} from '../../../../../../zustand/chatStore';

type Props = {
  item: Message;
  menuVisible: boolean;
  menuAnchor: {x: number; y: number} | null;
  setMenuVisible: React.Dispatch<React.SetStateAction<boolean>>;
  handleReply: () => void;
};
const MenuOnPressMessage = ({
  item,
  menuVisible,
  setMenuVisible,
  menuAnchor,
  handleReply,
}: Props) => {
  const dataAccount = useAppSelector(state => state.account.dataAccount);
  const {currentConversationId} = useChatStore();
  const sendMessage = useWebSocketStore(state => state.sendMessage);

  const handleDeleteMessage = () => {
    const bodyUnsendMessage = {
      action: 'UNSEND',
      conversationId: currentConversationId,
      messageId: item.message_id,
      username: item.username,
      userId: item.sender_id,
      timestamp: new Date().toISOString(),
    };
    sendMessage(bodyUnsendMessage as any);
    setMenuVisible(false);
  };
  const handlePinMessage = () => {
    const bodyPinMessage = {
      action: 'PIN',
      conversationId: currentConversationId,
      messageId: item.message_id,
      username: item.username,
      userId: item.sender_id,
      timestamp: new Date().toISOString(),
    };
    sendMessage(bodyPinMessage as any);
    setMenuVisible(false);
  };
  return (
    <Menu
      visible={menuVisible}
      onDismiss={() => setMenuVisible(false)}
      anchor={menuAnchor ? {x: menuAnchor.x, y: menuAnchor.y} : {x: 0, y: 0}}>
      <Menu.Item onPress={() => handlePinMessage()} title="Ghim tin nhắn" />
      {dataAccount.id == item.sender_id && (
        <Menu.Item onPress={() => handleDeleteMessage()} title="Xoá" />
      )}
      <Menu.Item
        onPress={() => {
          handleReply();
          setMenuVisible(false);
          console.log('Chuyển tiếp');
        }}
        title="Chuyển tiếp"
      />
    </Menu>
  );
};

export default MenuOnPressMessage;
