import {getConfig} from './httpClient';

export const createChatServices = (fetchRequest: any) => ({
  async getListConversation(userId: number) {
    try {
      const endpoint = `/conversation?userId=${userId}`;
      const data = await fetchRequest({
        url: getConfig().BASE_URL_ECHAT + endpoint,
        method: 'GET',
      });
      return Promise.resolve(data?.data);
    } catch (error) {
      console.error('getListConversation: ', error);
      return Promise.reject(error);
    }
  },
  async getHistoryChat(conversationId: string, limit: number, page: number) {
    try {
      const endpoint = `/chats/history?conversationId=${conversationId}&limit=${limit}&page=${page}`;
      const data = await fetchRequest({
        url: getConfig().BASE_URL_ECHAT + endpoint,
        method: 'GET',
      });
      return Promise.resolve(data?.data);
    } catch (error) {
      console.error('getListConversation: ', error);
      return Promise.reject(error);
    }
  },
  async getListUser() {
    try {
      const endpoint = `/getListUser`;
      const data = await fetchRequest({
        url: getConfig().BASE_URL_ECHAT + endpoint,
        method: 'GET',
      });
      return Promise.resolve(data?.data);
    } catch (error) {
      console.error('getListUser: ', error);
      return Promise.reject(error);
    }
  },
  async getOneOnOneConversation(userId: number, otherUserId: number) {
    try {
      const endpoint = `/getOneOnOneConversation?userId=${userId}&otherUserId=${otherUserId}`;
      const data = await fetchRequest({
        url: getConfig().BASE_URL_ECHAT + endpoint,
        method: 'GET',
      });
      return Promise.resolve(data?.data);
    } catch (error) {
      console.error('getListUser: ', error);
      return Promise.reject(error);
    }
  },

  async createNewConversations(body: any, participant: any) {
    try {
      const endpoint = `/conversations`;
      const data = await fetchRequest({
        url: getConfig().BASE_URL_ECHAT + endpoint,
        method: 'POST',
        body: JSON.stringify(body),
      });
      const endpoint2 = `/chats/${data?.data?.id}`;
      await fetchRequest({
        url: getConfig().BASE_URL_ECHAT + endpoint2,
        method: 'POST',
        body: JSON.stringify(participant),
      });
      return Promise.resolve(data?.data);
    } catch (error) {
      return Promise.reject(error);
    }
  },

  async getPinChat(id: string) {
    try {
      const endpoint = `/conversation/${id}/pins`;
      const data = await fetchRequest({
        url: getConfig().BASE_URL_ECHAT + endpoint,
        method: 'GET',
      });
      return Promise.resolve(data?.data);
    } catch (error) {
      return Promise.reject(error);
    }
  },
});
