import {IMessageSocket} from '../model/interface/socket.interface';

type EventType = 'open' | 'message' | 'error' | 'close';

class WebSocketService {
  public socket: WebSocket | null = null;
  private reconnectTimer: NodeJS.Timeout | null = null;
  private url: string = '';
  private listeners: Map<EventType, Set<Function>> = new Map();

  private isManualClose: boolean = false;

  private RECONNECT_INTERVAL = 5000;

  constructor() {
    this.listeners.set('open', new Set());
    this.listeners.set('message', new Set());
    this.listeners.set('error', new Set());
    this.listeners.set('close', new Set());
  }

  private emit(event: EventType, data: any) {
    this.listeners.get(event)?.forEach(callback => callback(data));
  }

  public on(event: EventType, callback: Function) {
    this.listeners.get(event)?.add(callback);
  }

  public off(event: EventType, callback: Function) {
    this.listeners.get(event)?.delete(callback);
  }

  public connect(accessToken: string) {
    if (this.socket && this.socket.readyState < 2) {
      return;
    }

    if (!accessToken) {
      console.log('🔌 Access token không tồn tại, không kết nối WebSocket.');
      return;
    }

    this.url = `ws://10.14.121.10:8095/ws?token=${accessToken}`;
    this.isManualClose = false;

    console.log('🔌 Đang cố gắng kết nối WebSocket...');
    this.socket = new WebSocket(this.url);
    this.setupEventListeners();
  }

  private setupEventListeners() {
    if (!this.socket) return;

    this.socket.onopen = () => {
      console.log('✅ Kết nối WebSocket đã được mở.');
      if (this.reconnectTimer) {
        clearTimeout(this.reconnectTimer);
        this.reconnectTimer = null;
      }
      this.emit('open', true);
    };

    this.socket.onmessage = event => {
      try {
        const message = JSON.parse(event.data);
        this.emit('message', message);
      } catch (error) {
        console.error('❌ Không thể parse tin nhắn JSON:', event.data);
        this.emit('error', {message: 'Invalid JSON received'});
      }
    };

    this.socket.onerror = (event: Event) => {
      console.error('❌ Lỗi WebSocket:', event);
      this.emit('error', event);
    };

    this.socket.onclose = event => {
      console.log(`🔌 Kết nối WebSocket đã đóng: ${event.code}`);
      this.emit('close', false);

      if (!this.isManualClose) {
        console.log(
          `🔁 Sẽ thử kết nối lại sau ${this.RECONNECT_INTERVAL / 1000} giây...`,
        );
        this.reconnectTimer = setTimeout(
          () => this.connect(this.url.split('token=')[1]),
          this.RECONNECT_INTERVAL,
        );
      }
    };
  }

  public sendMessage(message: IMessageSocket | any) {
    if (this.socket && this.socket.readyState === WebSocket.OPEN) {
      this.socket.send(JSON.stringify(message));
    } else {
      console.warn('⚠️ WebSocket chưa sẵn sàng. Không thể gửi tin nhắn.');
    }
  }

  public disconnect() {
    if (this.reconnectTimer) {
      clearTimeout(this.reconnectTimer);
      this.reconnectTimer = null;
    }
    if (this.socket) {
      console.log('🔌 Chủ động ngắt kết nối WebSocket.');
      this.isManualClose = true;
      this.socket.close();
    }
  }

  public getIsConnected(): boolean {
    return this.socket?.readyState === WebSocket.OPEN;
  }
}

export const socketService = new WebSocketService();
