import React, {useEffect, useRef, useState} from 'react';
import {
  View,
  TouchableOpacity,
  FlatList,
  KeyboardAvoidingView,
  Platform,
} from 'react-native';
import {useSafeAreaInsets, SafeAreaView} from 'react-native-safe-area-context';
import {useNavigation, useRoute} from '@react-navigation/native';
import {styles} from './styles';
import {useChatService} from '../../../hooks/apiHooks/useAccountInfoServices';
import MessageItem from './component/message-item';
import {
  Chat,
  IPinChat,
  Message,
  ParticipantListConversation,
} from '../../../model/interface/chat.interface';
import TextCM from '../../components/Text';
import {useAppSelector} from '../../../hooks/useRedux';
import {Icon} from '@ui-kitten/components';
import MessageInput from './component/message-input';
import Toast from 'react-native-toast-message';
import Avatar from '../../components/Avatar';
import {User, userUserStore} from '../../../zustand/userStore';
import {useChatStore} from '../../../zustand/chatStore';
import TypingIndicator from './component/typing-indicator';
import {GestureHandlerRootView} from 'react-native-gesture-handler';
import ModalDetail from './component/modal-detail';
import {CommonUtils} from '../../../utils';
import BottomSheet from '../../components/BottomSheet';

const Conversation = () => {
  const {dataAccount} = useAppSelector(state => state.account);
  const {
    listMessage,
    currentListMessage,
    currentMediaChat,
    isTyping,
    setListMessage,
    setCurrentListMessage,
  } = useChatStore();
  const route = useRoute<any>();
  const insets = useSafeAreaInsets();
  const navigation = useNavigation<any>();
  const [participants, setParticipants] = useState<
    ParticipantListConversation[]
  >([]);
  const {listUser} = userUserStore();
  const ChatService = useChatService();
  const [viewModalDetail, setViewModalDetail] = useState(false);
  const [pinChat, setPinChat] = useState<IPinChat[]>([]);
  const [positionPin, setPositionPin] = useState(80);
  const [messageReply, setMessageReply] = useState<Message>();
  const [showBtnScrollToTop, setShowBtnScrollToTop] = useState(false);
  const [isLoadingNewer, setIsLoadingNewer] = useState(false);

  const flatListRef = useRef<FlatList<any>>(null);
  const conversationId = route?.params?.conversationId;
  const conversationName = route?.params?.conversationName;
  const targetId = route?.params?.targetId;

  const getHistoryChat = async () => {
    try {
      if (!conversationId) {
        setListMessage([]);
        const usersChatWith = targetId
          .map((id: number) =>
            listUser.find((user: User) => user.user_id === id),
          )
          .filter(Boolean);
        const myProfile = listUser.find(
          (user: User) => user.user_id === dataAccount?.id,
        );
        setParticipants([
          ...usersChatWith.map((user: User) => ({
            user_id: user.user_id || 0,
            i_nick: `${usersChatWith?.first_name || ''} ${
              usersChatWith?.last_name || ''
            }`?.trim(),
            user,
          })),
          {
            user_id: dataAccount?.id || 0,
            i_nick: `${myProfile?.first_name || ''} ${
              myProfile?.last_name || ''
            }`?.trim(),
            user: myProfile,
          },
        ]);
        return;
      } else {
        const res = await ChatService.getHistoryChat(conversationId, 50, 1);
        if (res.data) {
          const data = res.data as Chat;
          if (data.messages.length > 0) {
            const newMessage = data.messages.reverse();
            setListMessage(newMessage);
            setCurrentListMessage(newMessage.slice(0, 20));
          }
          const newParticipants = data.participants.map(
            (item: ParticipantListConversation) => {
              const findedUser = listUser.find(
                (user: User) => user.user_id === item.user_id,
              );
              if (findedUser) {
                item.user = findedUser;
              }
              return item;
            },
          );
          setParticipants(newParticipants);
        }
      }
    } catch (error) {
      Toast.show({
        type: 'error',
        text1: 'Không thể lấy cuộc trò chuyện',
      });
    }
  };

  const getPinChat = async () => {
    try {
      const res = await ChatService.getPinChat(conversationId);
      if (res.data) {
        const data = res.data as IPinChat[];
        if (data.length > 0) {
          setPinChat(data);
        }
      }
    } catch (error) {
      Toast.show({
        type: 'error',
        text1: 'Không thể lấy cuộc trò chuyện',
      });
    }
  };

  useEffect(() => {
    getHistoryChat();
    getPinChat();
  }, []);

  const getConversationName = () => {
    if (participants.length > 2) {
      const names = participants.map(
        participant =>
          participant?.user?.first_name ||
          '' + ' ' + participant?.user?.last_name ||
          '',
      );
      return names.join(', ');
    } else {
      const findedUser = participants.find(
        (item: ParticipantListConversation) => item.user_id !== dataAccount?.id,
      );
      return (
        findedUser?.user?.first_name ||
        '' + ' ' + findedUser?.user?.last_name ||
        ''
      );
    }
  };

  const handleScroll = (options: {
    type: 'top' | 'bottom' | 'message';
    messageId?: string | number;
  }) => {
    if (!flatListRef.current) {
      console.log('FlatList ref is not available.');
      return;
    }

    const {type, messageId} = options;

    switch (type) {
      case 'bottom':
        const first20Message = listMessage.slice(0, 20);
        setCurrentListMessage(first20Message);
        setTimeout(() => {
          flatListRef?.current?.scrollToIndex({
            animated: true,
            index: 0,
          });
        }, 100);
        break;
      case 'top':
        const firstMessageCurrentView = listMessage.findIndex(
          item =>
            item.message_id ===
            currentListMessage[currentListMessage.length - 1].message_id,
        );
        if (firstMessageCurrentView === -1) {
          const listNewMessage = listMessage.slice(0, 21);
          setCurrentListMessage([...listNewMessage, ...currentListMessage]);
        } else {
          handleScroll({type: 'top'});
        }
        break;
      case 'message':
        handleScrollToMessage(messageId as string);
        break;
      default:
        console.log('Invalid scroll type');
        break;
    }
  };

  const handleScrollToMessage = (messageId: string | number) => {
    console.log('handleScrollToMessage', messageId);
    if (!messageId) {
      console.log('Vui lòng nhập ID tin nhắn.');
      return;
    }

    const targetIndex = listMessage.findIndex(
      msg => msg.message_id == messageId,
    );

    if (targetIndex === -1) {
      console.log(`Không tìm thấy tin nhắn với ID: ${messageId}`);
      return;
    }

    // 2. Xác định "cửa sổ" dữ liệu: 10 tin nhắn trước và 10 tin nhắn sau
    const startIndex = Math.max(0, targetIndex - 10);
    const endIndex = Math.min(listMessage.length, targetIndex + 11); // +11 để bao gồm cả tin nhắn mục tiêu

    // 3. Cắt và tạo ra mảng tin nhắn mới sẽ được hiển thị
    const newWindowMessages = listMessage.slice(startIndex, endIndex);

    // 4. Cập nhật state để FlatList render lại với dữ liệu mới
    setCurrentListMessage(newWindowMessages);

    // 5. Tìm index của tin nhắn mục tiêu trong mảng DỮ LIỆU MỚI
    const indexInNewWindow = newWindowMessages.findIndex(
      msg => msg.message_id == messageId,
    );

    // QUAN TRỌNG: Dùng setTimeout để đảm bảo FlatList đã render xong
    // dữ liệu mới trước khi thực hiện scroll.
    setTimeout(() => {
      if (flatListRef.current && indexInNewWindow !== -1) {
        flatListRef.current.scrollToIndex({
          animated: true,
          index: indexInNewWindow,
          viewPosition: 0.5, // 0.5 = cuộn đến giữa màn hình
        });
      }
    }, 100); // một khoảng delay nhỏ là đủ
  };

  const loadMore = (direction: 'up' | 'down') => {
    if (direction === 'up') {
      // handleScroll({type: 'bottom'});
      // Tìm thêm 20 tin nhắn về phía bên trên
      const lastMessageCurrentView = listMessage.findIndex(
        item =>
          item.message_id ===
          currentListMessage[currentListMessage.length - 1].message_id,
      );
      const listNewMessage = listMessage.slice(
        lastMessageCurrentView + 1,
        lastMessageCurrentView + 21,
      );
      setCurrentListMessage([...currentListMessage, ...listNewMessage]);
    } else if (direction === 'down') {
      if (isLoadingNewer) return;
      setIsLoadingNewer(true);

      const newestVisibleMessage = currentListMessage[0];
      if (newestVisibleMessage?.message_id === listMessage[0]?.message_id) {
        console.log('Đã ở tin nhắn mới nhất.');
        setIsLoadingNewer(false);
        return;
      }

      const newestVisibleIndex = listMessage.findIndex(
        msg => msg.message_id === newestVisibleMessage.message_id,
      );

      if (newestVisibleIndex === -1) {
        setIsLoadingNewer(false);
        return;
      }

      const startIndex = Math.max(0, newestVisibleIndex - 20);
      const newerMessages = listMessage.slice(startIndex, newestVisibleIndex);

      if (newerMessages.length > 0) {
        // Đây là nơi phép màu của maintainVisibleContentPosition xảy ra
        setCurrentListMessage([...newerMessages, ...currentListMessage]);
      }
      setTimeout(() => setIsLoadingNewer(false), 500);
    }
  };

  useEffect(() => {
    if (currentMediaChat.length > 0) {
      setListMessage([
        {
          message_id: Math.floor(Math.random() * 100),
          sender_id: dataAccount?.id || 0,
          message_content: JSON.stringify({
            text: '',
            attachments: currentMediaChat,
          }),
          timestamp: new Date().toISOString(),
          username: dataAccount?.email || '',
          reply_to: null,
          status: 1,
          sequence: 1,
        },
        ...listMessage,
      ]);
    }
  }, [currentMediaChat]);

  const renderPinnedMessage = () => {
    if (pinChat.length === 0) {
      return null;
    }
    const firstPin = pinChat[0];
    return (
      <TouchableOpacity
        onPress={() => {
          const idxPin = listMessage.findIndex(
            message => message.message_id === firstPin.id,
          );

          handleScroll({type: 'message', messageId: firstPin.id});
        }}
        style={[styles.pinnedContainer, {top: positionPin}]}>
        <Icon name="pin" fill="#007AFF" style={styles.pinIcon} />
        <TextCM style={styles.pinnedText} numberOfLines={1}>
          <TextCM style={{fontWeight: 'bold'}}>{firstPin.username}: </TextCM>
          {CommonUtils.getText(firstPin.message)}
        </TextCM>
      </TouchableOpacity>
    );
  };

  return (
    <GestureHandlerRootView style={{flex: 1}}>
      <SafeAreaView style={styles.container}>
        <View
          onLayout={args => {
            setPositionPin(args.nativeEvent.layout.height + insets.top);
          }}
          style={[styles.header, {paddingTop: insets.top > 0 ? 0 : 10}]}>
          <TouchableOpacity
            style={styles.backButton}
            onPress={() => navigation.goBack()}>
            <Icon name="arrow-ios-back" width={24} height={24} />
          </TouchableOpacity>

          <TouchableOpacity
            style={styles.userInfo}
            onPress={() => {
              setViewModalDetail(true);
            }}>
            <Avatar participants={participants} />
            <View style={styles.userTextInfo}>
              <TextCM style={styles.userName}>
                {conversationName || getConversationName()}
              </TextCM>
            </View>
          </TouchableOpacity>
          <View style={styles.headerActions}>
            <TouchableOpacity style={styles.headerButton}>
              <Icon name="phone" width={20} height={20} />
            </TouchableOpacity>
            <TouchableOpacity style={styles.headerButton}>
              <Icon name="video" width={20} height={20} />
            </TouchableOpacity>
            <TouchableOpacity style={styles.headerButton}>
              <Icon name="info" width={20} height={20} />
            </TouchableOpacity>
          </View>
        </View>
        {pinChat.length > 0 && renderPinnedMessage()}

        <FlatList
          ref={flatListRef}
          style={styles.chatContainer}
          data={currentListMessage}
          renderItem={({item}) => (
            <MessageItem
              handleScroll={handleScroll}
              repliedMessage={
                item.reply_to
                  ? listMessage.find(m => m.message_id == item.reply_to)
                  : undefined
              }
              setMessageReply={setMessageReply}
              item={item}
              type={
                item.status === 3
                  ? 'system'
                  : dataAccount.id == item.sender_id
                  ? 'me'
                  : 'other'
              }
            />
          )}
          onScroll={({nativeEvent}) => {
            setShowBtnScrollToTop(nativeEvent.contentOffset.y > 80);
            if (nativeEvent.contentOffset.y < 80) {
              loadMore('down');
            }
          }}
          onEndReachedThreshold={0.5}
          onEndReached={() => {
            loadMore('up');
          }}
          maintainVisibleContentPosition={{
            minIndexForVisible: 0,
            // autoscrollToContentThreshold: 100,
          }}
          keyExtractor={item => item.message_id}
          contentContainerStyle={styles.messagesList}
          showsVerticalScrollIndicator={false}
          inverted={true}
        />

        {isTyping && <TypingIndicator />}
        <KeyboardAvoidingView
          behavior={Platform.OS === 'ios' ? 'padding' : undefined}
          style={styles.inputContainer}>
          <MessageInput
            showBtnScrollToTop={showBtnScrollToTop}
            handleScroll={handleScroll}
            messageReply={messageReply}
            setMessageReply={setMessageReply}
            participants={participants}
            conversationId={conversationId}
            conversationName={conversationName}
          />
        </KeyboardAvoidingView>
      </SafeAreaView>
      {viewModalDetail && (
        <BottomSheet
          children={<ModalDetail />}
          onClose={() => setViewModalDetail(false)}
        />
      )}
    </GestureHandlerRootView>
  );
};

export default Conversation;
