import {
  TouchableOpacity,
  View,
  Animated,
  useWindowDimensions,
} from 'react-native';
import TextCM from '../../../../components/Text';
import {IConversation} from '../../../../../model/interface/chat.interface';
import {Color, NavigationName} from '../../../../../constants';
import {styles} from './styles';
import {DateUtils} from '../../../../../utils';
import {useNavigation} from '@react-navigation/native';
import Avatar from '../../../../../app/components/Avatar';
import {useChatStore} from '../../../../../zustand/chatStore';
import {Swipeable} from 'react-native-gesture-handler';
import {Icon} from '@ui-kitten/components';
import {useState} from 'react';
import {useAppSelector} from '../../../../../hooks/useRedux';
import {isEmpty} from 'lodash';

type Props = {
  item: IConversation;
};
const ChatItem = ({item}: Props) => {
  const dataAccount = useAppSelector(state => state.account.dataAccount);
  const navigation = useNavigation<any>();
  const {width} = useWindowDimensions();
  const parseLastMessage = JSON.parse(item?.lastMessage.text || '{}');
  const lastMessage = parseLastMessage?.text || '';
  const {currentConversationId, setCurrentConversationId, setListMessage} =
    useChatStore();

  const renderRightActions = (
    progress: Animated.AnimatedInterpolation<number>,
    dragX: Animated.AnimatedInterpolation<number>,
  ) => {
    // animate translateX từ 120 → 0 khi vuốt
    const trans = dragX.interpolate({
      inputRange: [-(width / 2), 0],
      outputRange: [0, width / 2],
      extrapolate: 'clamp',
    });

    const scale = dragX.interpolate({
      inputRange: [-80, -40, 0],
      outputRange: [1.2, 1.0, 0.8],
      extrapolate: 'clamp',
    });

    return (
      <Animated.View
        style={{
          width: 240,
          flexDirection: 'row',
          justifyContent: 'space-evenly',
          alignItems: 'center',
          transform: [{translateX: trans}],
        }}>
        <TouchableOpacity
          style={{backgroundColor: Color.gray, borderRadius: 100, padding: 10}}>
          <Icon name="menu" width={30} height={30} fill="black" />
        </TouchableOpacity>
        <TouchableOpacity
          style={{backgroundColor: Color.gray, borderRadius: 100, padding: 10}}>
          <Icon name="bell" width={30} height={30} fill="black" />
        </TouchableOpacity>
        <TouchableOpacity
          style={{backgroundColor: Color.gray, borderRadius: 100, padding: 10}}>
          <Icon name="trash" width={30} height={30} fill="red" />
        </TouchableOpacity>

        {/* <Animated.View style={{transform: [{scale}], marginRight: 8}}>
          <TouchableOpacity
            style={[styles.actionButton, styles.more]}
            onPress={() => {}}
            activeOpacity={0.6}>
            <TextCM style={styles.actionText}>More</TextCM>
          </TouchableOpacity>
        </Animated.View>

        <Animated.View style={{transform: [{scale}]}}>
          <TouchableOpacity
            style={[styles.actionButton, styles.delete]}
            onPress={() => {}}
            activeOpacity={0.6}>
            <TextCM style={styles.actionText}>Delete</TextCM>
          </TouchableOpacity>
        </Animated.View> */}
      </Animated.View>
    );
  };

  return (
    <Swipeable
      friction={2}
      rightThreshold={40}
      overshootRight={false} // không overshoot quá vùng
      useNativeAnimations={true} // chuyển interpolation sang native driver
      // renderLeftActions={renderLeftAction}
      renderRightActions={renderRightActions}>
      <TouchableOpacity
        style={styles.chatItem}
        onPress={() => {
          if (item.id !== currentConversationId) {
            setListMessage([]);
            setCurrentConversationId(item.id);
          }
          navigation.navigate(NavigationName.Conversation, {
            conversationId: item.id,
            conversationName: item.conversationName,
          });
        }}>
        <Avatar participants={item.participants} />

        <View style={styles.chatContent}>
          <View style={styles.chatHeader}>
            <TextCM style={styles.chatName} numberOfLines={1}>
              {item.conversationName}
            </TextCM>
            <TextCM style={styles.chatTime}>
              {DateUtils.convertDateToDDMMYYYY_H_M(
                item?.lastMessage?.timestamp,
              )}
            </TextCM>
          </View>
          <View style={styles.chatFooter}>
            <TextCM style={styles.chatMessage} numberOfLines={1}>
              {`${
                item.lastMessage.username == dataAccount.email
                  ? 'You'
                  : item.lastMessage.username
              }:`}{' '}
              {item.lastMessage.status == 2
                ? 'Đã thu hồi một tin nhắn'
                : lastMessage}
            </TextCM>
          </View>
        </View>
      </TouchableOpacity>
    </Swipeable>
  );
};

export default ChatItem;
