// src/store/useWebSocketStore.ts
import {create} from 'zustand';
import {immer} from 'zustand/middleware/immer'; // Sử dụng immer để thao tác với trạng thái dễ dàng hơn
import {IMessageSocket} from '../model/interface/socket.interface'; // Import IMessageSocket nếu cần
import {socketService} from '../socket/socketService';

interface WebSocketState {
  isConnected: boolean;
  lastMessage: any | null;
  error: any | null;
  // Actions
  connectWebSocket: (accessToken: string) => void;
  sendMessage: (message: IMessageSocket) => void;
  disconnectWebSocket: () => void;
  // Internal listeners (không cần export, chỉ để Zustand store lắng nghe sự kiện từ socketService)
  _handleSocketOpen: () => void;
  _handleSocketClose: () => void;
  _handleSocketMessage: (message: any) => void;
  _handleSocketError: (error: any) => void;
}

// Tạo store Zustand
export const useWebSocketStore = create<WebSocketState>()(
  immer((set, get) => ({
    isConnected: socketService.getIsConnected(),
    lastMessage: null,
    error: null,

    // Actions để tương tác với socketService
    connectWebSocket: (accessToken: string) => {
      // Chỉ kết nối nếu chưa có kết nối hoặc accessToken đã thay đổi
      // và socket chưa được khởi tạo hoặc đang đóng
      if (
        accessToken &&
        !socketService.getIsConnected() &&
        socketService.socket?.readyState !== WebSocket.CONNECTING
      ) {
        socketService.connect(accessToken);
      } else if (!accessToken) {
        socketService.disconnect();
      }
    },

    sendMessage: (message: IMessageSocket | any) => {
      socketService.sendMessage(message);
    },

    disconnectWebSocket: () => {
      socketService.disconnect();
    },

    // Các hàm lắng nghe sự kiện từ socketService để cập nhật trạng thái của store
    _handleSocketOpen: () => {
      set(state => {
        state.isConnected = true;
        state.error = null; // Xóa lỗi nếu kết nối thành công
      });
    },
    _handleSocketClose: () => {
      set(state => {
        state.isConnected = false;
      });
    },
    _handleSocketMessage: (message: any) => {
      set(state => {
        state.lastMessage = message;
      });
    },
    _handleSocketError: (err: any) => {
      set(state => {
        state.error = err;
      });
    },
  })),
);

// Lắng nghe các sự kiện từ socketService và cập nhật store Zustand
// Điều này cần được gọi một lần khi ứng dụng khởi tạo,
// ví dụ trong App.tsx hoặc một component gốc.
export const initializeWebSocketListeners = () => {
  const {
    _handleSocketOpen,
    _handleSocketClose,
    _handleSocketMessage,
    _handleSocketError,
  } = useWebSocketStore.getState();

  socketService.on('open', _handleSocketOpen);
  socketService.on('close', _handleSocketClose);
  socketService.on('message', _handleSocketMessage);
  socketService.on('error', _handleSocketError);

  // Quan trọng: Xử lý khi component unmount hoặc khi ứng dụng tắt
  // để loại bỏ các listener và tránh memory leaks.
  // Tuy nhiên, với một singleton service như socketService, các listener này
  // thường tồn tại suốt vòng đời ứng dụng.
  // Nếu bạn muốn clean up, bạn sẽ cần một hàm `cleanupWebSocketListeners`
  // và gọi nó khi ứng dụng bị tắt hoàn toàn (ít phổ biến trong ứng dụng React SPA).
};

// Gọi initializeWebSocketListeners một lần khi ứng dụng khởi động
// (xem cách sử dụng bên dưới)
