import {Icon} from '@ui-kitten/components';
import {TextInput, TouchableOpacity, View} from 'react-native';
import {styles} from '../../styles';
import {useEffect, useRef, useState} from 'react';
import {
  Message,
  ParticipantListConversation,
} from '../../../../../model/interface/chat.interface';
import Toast from 'react-native-toast-message';
import {useAppSelector} from '../../../../../hooks/useRedux';
import {useWebSocketStore} from '../../../../../zustand/useWebSocketStore';
import {useChatService} from '../../../../../hooks/apiHooks/useAccountInfoServices';
import {useChatStore} from '../../../../../zustand/chatStore';
import CropPickerComponent, {
  ImagePicked,
} from '../../../../components/ImageCropPicker';
import {CommonUtils} from '../../../../../utils';
import useDebounce from '../../../../../hooks/useDebounce';
import TextCM from '../../../../components/Text';
import {useSafeAreaInsets} from 'react-native-safe-area-context';

type Props = {
  showBtnScrollToTop: boolean;
  participants: ParticipantListConversation[];
  conversationId: string;
  conversationName: string;
  messageReply?: Message;
  setMessageReply: React.Dispatch<React.SetStateAction<Message | undefined>>;
  handleScroll: (options: {
    type: 'top' | 'bottom' | 'message';
    messageId?: string | number;
  }) => void;
};
const MessageInput = ({
  showBtnScrollToTop,
  participants,
  conversationId,
  conversationName,
  messageReply,
  setMessageReply,
  handleScroll,
}: Props) => {
  const dataAccount = useAppSelector(state => state.account.dataAccount);
  const ChatService = useChatService();
  const sendMessage = useWebSocketStore(state => state.sendMessage);
  const [heightContainerInput, setHeightContainerInput] = useState(0);
  const {
    listConversation,
    currentMediaChat,
    setListConversation,
    setListCurrentViewConversation,
    setCurrentConversationId,
    setCurrentMediaChat,
  } = useChatStore();
  const [message, setMessage] = useState('');
  const [chatId, setChatId] = useState(conversationId);
  const typingTimeoutRef = useRef<NodeJS.Timeout | null>(null);
  const isTypingRef = useRef(false);

  const sendMessageTyping = async () => {
    const bodyIsTyping = {
      action: 'USER_TYPING',
      conversationId: conversationId,
      conversationName: conversationName,
      status: 2,
      createdBy: {
        userId: dataAccount?.id,
        username: dataAccount?.email,
        custId: dataAccount?.custId,
        orgIn: dataAccount?.orgIn,
      },
      participants: participants.map((item: ParticipantListConversation) => {
        return {
          userId: item.user_id,
          username: item.i_nick,
        };
      }),
      isGroup: true,
      timestamp: new Date().toISOString(),
    };
    sendMessage(bodyIsTyping as any);
  };

  const sendMessageStopTyping = async () => {
    const bodyStopTyping = {
      action: 'USER_STOP_TYPING',
      conversationId: conversationId,
      conversationName: conversationName,
      status: 2,
      createdBy: {
        userId: dataAccount?.id,
        username: dataAccount?.email,
        custId: dataAccount?.custId,
        orgIn: dataAccount?.orgIn,
      },
      participants: participants.map((item: ParticipantListConversation) => {
        return {
          userId: item.user_id,
          username: item.i_nick,
        };
      }),
      isGroup: true,
      timestamp: new Date().toISOString(),
    };
    sendMessage(bodyStopTyping as any);
  };

  const handleTyping = (text: string) => {
    setMessage(text);
    if (!isTypingRef.current) {
      sendMessageTyping();
      isTypingRef.current = true;
    }
    if (typingTimeoutRef.current) {
      clearTimeout(typingTimeoutRef.current);
    }
    typingTimeoutRef.current = setTimeout(() => {
      sendMessageStopTyping();
      isTypingRef.current = false;
    }, 3000);
  };

  const createNewConversation = async () => {
    try {
      const body = {
        conversationName: conversationName,
        topic: '',
        status: 1,
        description: '',
        userId: dataAccount?.id || 0,
        custId: dataAccount?.custId || 0,
        orgIn: dataAccount?.orgIn || '',
        email: dataAccount.email || '',
        dbSuffix: '00001',
      };
      const res = await ChatService.createNewConversations(body, {
        participants: participants.map((item: ParticipantListConversation) => {
          return {
            userId: item.user_id,
            custId: item.user?.cust_id,
            iNick: `${item.user?.first_name || ''} ${
              item.user?.last_name || ''
            }`?.trim(),
            orgIn: item.user?.org_in,
          };
        }),
      });
      if (res) {
        const bodyN_SUB = {
          action: 'N_SUB',
          topic: res?.id,
        };
        sendMessage(bodyN_SUB as any);
        const bodyNewConversation = {
          action: 'NEW_CONVERSATION',
          conversationId: res?.id,
          conversationName: conversationName,
          status: 2,
          createdBy: {
            userId: dataAccount?.id,
            username: dataAccount?.email,
            custId: dataAccount?.custId,
            orgIn: dataAccount?.orgIn,
          },
          participants: participants.map(
            (item: ParticipantListConversation) => {
              return {
                userId: item.user_id,
                username: item.i_nick,
              };
            },
          ),
          isGroup: true,
          timestamp: new Date().toISOString(),
        };
        const newConverSation = {
          id: res?.id,
          conversationName: conversationName,
          status: 2,
          description: '',
          userId: dataAccount?.id || 0,
          custId: dataAccount?.custId || 0,
          orgIn: dataAccount?.orgIn || '',
          lastMessage: {
            text: JSON.stringify({text: message, attachments: []}),
            status: 2,
            sender_id: dataAccount?.id || 0,
            username: dataAccount?.email || '',
            timestamp: new Date().toISOString(),
          },
          participants: participants.map(
            (item: ParticipantListConversation) => {
              return {
                user_id: item.user_id,
                i_nick: item.i_nick,
                user: item.user,
              };
            },
          ),
        };
        setCurrentConversationId(res?.id);
        setListConversation([newConverSation, ...listConversation]);
        setListCurrentViewConversation([newConverSation, ...listConversation]);
        sendMessage(bodyNewConversation as any);
        setChatId(res?.id);
        sendNewMessage(res?.id);
      }
    } catch (error) {
      Toast.show({
        type: 'error',
        text2: 'Lỗi khi tạo cuộc trò chuyện',
      });
    }
  };

  const sendNewMessage = async (id?: string) => {
    try {
      const body = {
        action: 'SEND',
        conversationId: id || conversationId || chatId,
        content: {
          text: message,
          attachments: [],
          replyTo: messageReply ? messageReply.message_id?.toString() : null,
        },
        replyTo: messageReply ? messageReply.message_id?.toString() : null,
        type: 'text',
        from: {
          userId: dataAccount.id || 0,
          username: dataAccount.email || '',
        },
        to: participants.map((item: ParticipantListConversation) => {
          return {
            userId: item.user_id,
            username: item.i_nick,
          };
        }),
        status: 1,
        timestamp: new Date().toISOString(),
      };
      sendMessage(body);
      setMessage('');
      setMessageReply(undefined);
    } catch (error) {
      Toast.show({
        type: 'error',
        text2: 'Lỗi khi gửi tin nhắn',
      });
    }
  };

  const handleSendMessage = async () => {
    try {
      if (message) {
        if (!conversationId) {
          await createNewConversation();
        } else {
          sendNewMessage();
        }
        handleScroll({type: 'bottom'});
      }
    } catch (error) {
      console.error(error);
      Toast.show({
        type: 'error',
        text1: 'Thông báo',
        text2: 'Lỗi khi gửi tin nhắn',
      });
    }
  };

  const handleTakePhoto = async () => {
    try {
      let image = (await CropPickerComponent.TakePhoto({
        cropping: false,
        includeBase64Enabled: false,
        useFrontCameraEnabled: true,
      })) as any;
      console.log('image', image);
    } catch (error) {
      console.error(error);
      return;
    }
  };

  const handleSelectImage = async () => {
    try {
      const dataSelect = (await CropPickerComponent.ChoosePhoto({
        cropping: true,
      })) as ImagePicked;
      console.log('dataSelect', dataSelect);
      setCurrentMediaChat([dataSelect, ...currentMediaChat]);
    } catch (error) {
      console.log(error);
    }
  };

  const handleGetFromFile = async () => {
    try {
      const dataSelect = await CommonUtils.handleGetFile();
      console.log('handleGetFromFile', dataSelect);
    } catch (error) {
      console.error(error);
    }
  };

  return (
    <View
      style={styles.inputRow}
      onLayout={e => setHeightContainerInput(e.nativeEvent.layout.height)}>
      {messageReply && (
        <View
          style={[
            {
              position: 'absolute',
              left: 0,
              right: 0,
              height: 45,
              backgroundColor: '#f0f4f8',
              flexDirection: 'row',
              alignItems: 'center',
              paddingHorizontal: 15,
              opacity: 0.85,
            },
            {bottom: heightContainerInput},
          ]}>
          <View style={{flex: 1}}>
            <TextCM style={styles.replyText}>{messageReply.username}</TextCM>
            <TextCM numberOfLines={1} style={styles.replyText}>
              {CommonUtils.getText(messageReply.message_content)}
            </TextCM>
          </View>
          <TouchableOpacity
            onPress={() => setMessageReply(undefined)}
            style={{}}>
            <Icon name="close" width={20} height={20} />
          </TouchableOpacity>
        </View>
      )}
      {showBtnScrollToTop && (
        <TouchableOpacity
          style={[
            {
              position: 'absolute',
              height: 45,
              flexDirection: 'row',
              alignItems: 'center',
              paddingHorizontal: 15,
            },
            {bottom: heightContainerInput + 50, right: 15},
          ]}
          onPress={() => handleScroll({type: 'bottom'})}>
          <Icon name="arrow-downward" fill="blue" width={20} height={20} />
        </TouchableOpacity>
      )}
      <TouchableOpacity style={styles.inputButton} onPress={handleGetFromFile}>
        <Icon name="plus-circle" width={20} height={20} />
      </TouchableOpacity>

      <TouchableOpacity style={styles.inputButton} onPress={handleSelectImage}>
        <Icon name="camera" width={20} height={20} />
      </TouchableOpacity>

      <TouchableOpacity style={styles.inputButton} onPress={handleTakePhoto}>
        <Icon name="mic" width={20} height={20} />
      </TouchableOpacity>

      <View style={styles.textInputContainer}>
        <TextInput
          style={styles.textInput}
          placeholder="Aa"
          value={message}
          onChangeText={handleTyping}
          multiline
        />
        <TouchableOpacity style={styles.emojiButton}></TouchableOpacity>
      </View>

      <TouchableOpacity style={styles.sendButton} onPress={handleSendMessage}>
        <Icon name="navigation-2" width={20} height={20} />
      </TouchableOpacity>
    </View>
  );
};

export default MessageInput;
